import json
import requests
import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON: {e}")
    if unknown_key not in data:
        raise KeyError(f"Key '{unknown_key}' not found in JSON data.")
    url = data[unknown_key]
    if not url or not isinstance(url, str):
        raise ValueError(f"URL for key '{unknown_key}' is empty or invalid.")
    timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"
    if save_dir is None:
        save_dir = os.getcwd()
    filepath = os.path.join(save_dir, filename)
    legacy = url.startswith("http://localhost") or "dev." in url
    try:
        response = requests.get(url, verify=not legacy)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ConnectionError(f"Failed to download file: {e}")
    with open(filepath, 'wb') as f:
        f.write(response.content)
    return os.path.abspath(filepath)

