import requests
import json
import pandas as pd
import seaborn as sns
HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not url or not parameters:
        raise Exception("URL and parameters must be provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
    except Exception as e:
        raise Exception(f"Failed to retrieve data: {e}")
    if not data:
        raise Exception("Empty data received from API.")
    try:
        df = pd.DataFrame(data)
    except Exception as e:
        raise Exception(f"Invalid data format: {e}")
    if df.empty:
        raise Exception("DataFrame is empty after conversion.")
    numeric_cols = df.select_dtypes(include=['number']).columns
    if len(numeric_cols) < 2:
        raise Exception("Not enough numeric columns for correlation heatmap.")
    corr = df[numeric_cols].corr()
    ax = sns.heatmap(corr, annot=True, cmap='coolwarm')
    return (df, ax)

