import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    if not url or not filename:
        raise ValueError("URL and filename must be non-empty strings.")

    try:
        DOWNLOAD_DIR.mkdir(exist_ok=True)
        legacy = "localhost" in url or "dev." in url
        response = requests.get(url, stream=True, timeout=10, verify=not legacy)
        response.raise_for_status()
        zip_path = DOWNLOAD_DIR / filename
        with open(zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except Exception as e:
        return ("Error: Download failed", [])

    try:
        ZIP_DIR.mkdir(exist_ok=True)
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
        filenames = [str(p.name) for p in ZIP_DIR.iterdir()]
        return ("Success", filenames)
    except Exception as e:
        return ("Error: Extraction failed", [])
